[et_pb_section fb_built="1" admin_label="RM Process Plan Editorial" _builder_version="4.27.4" use_custom_width="on" width_unit="off" custom_width_px="100%" custom_padding="0px||0px||false|false" global_colors_info="{}"][et_pb_row _builder_version="4.27.4" width="100%" max_width="100%" use_custom_gutter="on" gutter_width="1" custom_padding="0px||0px||false|false" global_colors_info="{}"][et_pb_column type="4_4" _builder_version="4.27.4" global_colors_info="{}"][et_pb_code admin_label="RM Process Plan Editorial — Code" _builder_version="4.27.4" global_colors_info="{}"]<!-- ============================================================
     RM PROCESS PLAN EDITORIAL — Bloque 4 "Cómo trabajamos" del Plan
     Editorial Anual (Divi 5, Code Module)
     Marca: Rodmedia · Reestructuración web
     Mismo sistema que "Cómo trabajamos" de Diseño Web y Tienda Online
     (línea vertical central con pasos alternando imagen/texto a cada
     lado), extendido a 5 pasos en vez de 4. El quinto paso ("Seguimiento")
     solo aplica al nivel Gestionado, así que lleva una etiqueta extra
     bajo el título para dejarlo claro sin tener que repetir "(solo en
     Gestionado)" dentro de la frase.

     Imágenes: igual que en los otros bloques de proceso, cada paso
     tiene un hueco de imagen con icono de marca sobre fondo en
     degradado en vez de foto — para poner una foto real, sustituye el
     div .rm-process-pe__step-media por un <img> apuntando a la
     Biblioteca de medios de WordPress.

     Movimiento (GSAP + ScrollTrigger por CDN, cdnjs): cada paso entra
     con imagen y texto desfasados, la línea central se dibuja según
     el scroll (scrub), icono flotando. Respeta prefers-reduced-motion.

     ANTES DE PUBLICAR:
     1) Si ya cargas Playfair Display / Inter desde el Theme Builder de
        Divi, borra el @import de aquí para evitar cargarlas dos veces.
     2) Sustituye los 5 huecos de imagen por fotos reales si quieres.
     ============================================================ -->

<section id="como-trabajamos" class="rm-process-pe" aria-labelledby="rm-process-pe-title">

  <div class="rm-process-pe__bg" aria-hidden="true">
    <div class="rm-process-pe__glow rm-process-pe__glow--blue"></div>
    <div class="rm-process-pe__glow rm-process-pe__glow--orange"></div>
  </div>

  <div class="rm-process-pe__container">

    <div class="rm-process-pe__head" data-animate>
      <h2 id="rm-process-pe-title" class="rm-process-pe__title">Cómo trabajamos</h2>
    </div>

    <div class="rm-process-pe__timeline-wrap">
    <div class="rm-process-pe__spine" aria-hidden="true"></div>
    <ol class="rm-process-pe__timeline">

      <li class="rm-process-pe__step" data-animate>
        <!-- FOTO AQUÍ: llamada / sesión inicial -->
        <div class="rm-process-pe__step-media">
          <svg width="30" height="30" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <path d="M6.5 3.5c1 0 1.9.6 2.3 1.6l.7 1.8c.4.9.1 1.9-.6 2.5l-1 .9c.8 2 2.4 3.6 4.4 4.4l.9-1c.6-.7 1.6-1 2.5-.6l1.8.7c1 .4 1.6 1.3 1.6 2.3v1.6c0 1.4-1.3 2.5-2.7 2.2-7-1.4-12.4-6.8-13.8-13.8C1.9 5 3 3.7 4.4 3.7h2.1Z" stroke="#ffffff" stroke-width="1.5" stroke-linejoin="round"/>
          </svg>
        </div>
        <div class="rm-process-pe__step-body">
          <span class="rm-process-pe__step-num">01</span>
          <h3 class="rm-process-pe__step-title">Sesión inicial</h3>
          <p class="rm-process-pe__step-text">Me cuentas tu negocio, tu público y tus ideas, aunque estén desordenadas.</p>
        </div>
      </li>

      <li class="rm-process-pe__step rm-process-pe__step--reverse" data-animate>
        <!-- FOTO AQUÍ: notas / investigación -->
        <div class="rm-process-pe__step-media">
          <svg width="28" height="28" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <circle cx="10.5" cy="10.5" r="6.5" stroke="#ffffff" stroke-width="1.5"/>
            <path d="M15.3 15.3 20 20" stroke="#ffffff" stroke-width="1.5" stroke-linecap="round"/>
          </svg>
        </div>
        <div class="rm-process-pe__step-body">
          <span class="rm-process-pe__step-num">02</span>
          <h3 class="rm-process-pe__step-title">Orden e investigación</h3>
          <p class="rm-process-pe__step-text">Ordeno tus ideas con tus propias palabras y las completo con datos comprobados.</p>
        </div>
      </li>

      <li class="rm-process-pe__step" data-animate>
        <!-- FOTO AQUÍ: calendario / títulos -->
        <div class="rm-process-pe__step-media">
          <svg width="28" height="28" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <rect x="3.5" y="5" width="17" height="15" rx="2" stroke="#ffffff" stroke-width="1.5"/>
            <path d="M3.5 9.5h17M8 3v3.5M16 3v3.5" stroke="#ffffff" stroke-width="1.5" stroke-linecap="round"/>
            <path d="M7.5 13h2.5M11.5 13h2.5M15.5 13H17M7.5 16.3h2.5M11.5 16.3h2.5" stroke="#ffffff" stroke-width="1.4" stroke-linecap="round"/>
          </svg>
        </div>
        <div class="rm-process-pe__step-body">
          <span class="rm-process-pe__step-num">03</span>
          <h3 class="rm-process-pe__step-title">Títulos y calendario</h3>
          <p class="rm-process-pe__step-text">Preparo los títulos SEO del año y los reparto por meses según las fechas clave de tu sector.</p>
        </div>
      </li>

      <li class="rm-process-pe__step rm-process-pe__step--reverse" data-animate>
        <!-- FOTO AQUÍ: panel de trabajo -->
        <div class="rm-process-pe__step-media">
          <svg width="28" height="28" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <rect x="3.5" y="4" width="17" height="16" rx="2" stroke="#ffffff" stroke-width="1.5"/>
            <path d="M8.5 4v16M14.5 4v16" stroke="#ffffff" stroke-width="1.5"/>
            <path d="M5.5 8h1.5M5.5 11h1.5M10.5 8h2M10.5 11h2M16.5 8h1.5M16.5 11h1.5" stroke="#ffffff" stroke-width="1.4" stroke-linecap="round"/>
          </svg>
        </div>
        <div class="rm-process-pe__step-body">
          <span class="rm-process-pe__step-num">04</span>
          <h3 class="rm-process-pe__step-title">Panel de trabajo</h3>
          <p class="rm-process-pe__step-text">Te entrego el panel con todo el año cargado, listo para trabajar.</p>
        </div>
      </li>

      <li class="rm-process-pe__step" data-animate>
        <!-- FOTO AQUÍ: revisión mensual -->
        <div class="rm-process-pe__step-media">
          <svg width="28" height="28" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <path d="M20 11a8 8 0 1 1-2.6-5.9" stroke="#ffffff" stroke-width="1.6" stroke-linecap="round"/>
            <path d="M20 4v4.5h-4.5" stroke="#ffffff" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </div>
        <div class="rm-process-pe__step-body">
          <span class="rm-process-pe__step-num">05</span>
          <h3 class="rm-process-pe__step-title">Seguimiento <span class="rm-process-pe__step-badge">Solo en Gestionado</span></h3>
          <p class="rm-process-pe__step-text">Cada mes revisamos el calendario, ajustamos lo necesario y preparo los contenidos.</p>
        </div>
      </li>

    </ol>
    </div>

  </div>
</section>

<style>
  @import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,600;0,700;1,600;1,700&family=Inter:wght@400;500;600;700&display=swap');

  .rm-process-pe {
    --rm-primary: #0f0f1e;
    --rm-blue: #3a7bd5;
    --rm-orange: #e8531a;
    --rm-light: #f8f8fb;
    --rm-text-muted: #9aa3bd;
    --rm-text-muted-2: #7d84a0;
    --rm-radius: 8px;
    --rm-radius-lg: 20px;
    --rm-transition: 0.3s ease;
    --rm-font-display: "Playfair Display", Georgia, "Times New Roman", serif;
    --rm-font-body: "Inter", -apple-system, BlinkMacSystemFont, sans-serif;

    position: relative;
    overflow: hidden;
    background: var(--rm-primary);
    color: var(--rm-light);
    font-family: var(--rm-font-body);
    padding: 110px 20px 120px;
    box-sizing: border-box;
  }

  .rm-process-pe *,
  .rm-process-pe *::before,
  .rm-process-pe *::after {
    box-sizing: inherit;
  }

  /* ---------- Fondo: dos glows sutiles ---------- */
  .rm-process-pe__bg {
    position: absolute;
    inset: 0;
    z-index: 0;
    overflow: hidden;
    pointer-events: none;
  }

  .rm-process-pe__glow {
    position: absolute;
    border-radius: 50%;
    filter: blur(110px);
    opacity: 0.22;
  }

  .rm-process-pe__glow--blue {
    width: 500px;
    height: 500px;
    top: -180px;
    right: -140px;
    background: var(--rm-blue);
  }

  .rm-process-pe__glow--orange {
    width: 440px;
    height: 440px;
    bottom: -180px;
    left: -140px;
    background: var(--rm-orange);
  }

  /* ---------- Contenedor ---------- */
  .rm-process-pe__container {
    position: relative;
    z-index: 1;
    max-width: 980px;
    margin: 0 auto;
  }

  /* El contenido se renderiza visible por defecto: si GSAP/ScrollTrigger
     no cargan desde el CDN, nada depende de JS para mostrarse. Cuando
     sí cargan, gsap.from() anima desde un estado inicial oculto hasta
     este estado natural al entrar en scroll — ver el <script> final. */

  /* ---------- Cabecera ---------- */
  .rm-process-pe__head {
    text-align: center;
    margin-bottom: 72px;
  }

  .rm-process-pe__title {
    font-family: var(--rm-font-display);
    font-weight: 700;
    font-size: clamp(1.875rem, 1.45rem + 2vw, 2.75rem);
    line-height: 1.18;
    letter-spacing: -0.01em;
    color: var(--rm-light);
    margin: 0;
  }

  /* ---------- Línea central (solo escritorio) ---------- */
  .rm-process-pe__timeline-wrap {
    position: relative;
  }

  .rm-process-pe__timeline {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 64px;
  }

  .rm-process-pe__spine {
    position: absolute;
    top: 6px;
    bottom: 6px;
    left: 50%;
    width: 2px;
    margin-left: -1px;
    background: linear-gradient(180deg, var(--rm-blue), var(--rm-orange), var(--rm-blue));
    opacity: 0.4;
    transform: scaleY(1);
    transform-origin: top center;
  }

  /* ---------- Paso: grid de 3 columnas [contenido | eje | contenido] ---------- */
  .rm-process-pe__step {
    position: relative;
    display: grid;
    grid-template-columns: 1fr 64px 1fr;
    align-items: center;
    gap: 0 28px;
  }

  .rm-process-pe__step-media {
    grid-column: 1;
    grid-row: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    aspect-ratio: 4 / 3;
    border-radius: var(--rm-radius-lg);
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    box-shadow: 0 20px 48px rgba(0, 0, 0, 0.3);
    transition: transform 0.4s ease, box-shadow 0.4s ease;
  }

  .rm-process-pe__step:hover .rm-process-pe__step-media {
    transform: scale(1.035) rotate(-0.8deg);
    box-shadow: 0 26px 60px rgba(0, 0, 0, 0.4);
  }

  .rm-process-pe__step--reverse:hover .rm-process-pe__step-media {
    transform: scale(1.035) rotate(0.8deg);
  }

  .rm-process-pe__step-media svg {
    transform-origin: center;
  }

  .rm-process-pe__step-body {
    grid-column: 3;
    grid-row: 1;
  }

  .rm-process-pe__step--reverse .rm-process-pe__step-media {
    grid-column: 3;
  }

  .rm-process-pe__step--reverse .rm-process-pe__step-body {
    grid-column: 1;
    text-align: right;
  }

  .rm-process-pe__step-num {
    position: relative;
    z-index: 2;
    display: inline-block;
    font-family: var(--rm-font-display);
    font-weight: 700;
    font-size: 15px;
    letter-spacing: 0.04em;
    background: linear-gradient(135deg, var(--rm-blue), var(--rm-orange));
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    margin-bottom: 10px;
  }

  .rm-process-pe__step-title {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 10px;
    font-family: var(--rm-font-display);
    font-weight: 700;
    font-size: 22px;
    line-height: 1.25;
    color: var(--rm-light);
    margin: 0 0 10px;
  }

  .rm-process-pe__step--reverse .rm-process-pe__step-title {
    justify-content: flex-end;
  }

  .rm-process-pe__step-badge {
    display: inline-block;
    padding: 4px 10px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.14);
    font-family: var(--rm-font-body);
    font-weight: 600;
    font-size: 11px;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    color: var(--rm-text-muted);
    vertical-align: middle;
  }

  .rm-process-pe__step-text {
    font-size: 15px;
    line-height: 1.65;
    color: var(--rm-text-muted);
    margin: 0;
    max-width: 38ch;
  }

  .rm-process-pe__step--reverse .rm-process-pe__step-text {
    margin-left: auto;
  }

  @media (prefers-reduced-motion: reduce) {
    .rm-process-pe__step:hover .rm-process-pe__step-media,
    .rm-process-pe__step--reverse:hover .rm-process-pe__step-media {
      transform: none;
    }
  }

  /* ---------- Responsive ---------- */
  @media (max-width: 860px) {
    .rm-process-pe {
      padding: 80px 20px 90px;
    }

    .rm-process-pe__head {
      margin-bottom: 52px;
    }

    .rm-process-pe__timeline {
      gap: 48px;
    }

    .rm-process-pe__spine {
      display: none;
    }

    .rm-process-pe__step,
    .rm-process-pe__step--reverse {
      grid-template-columns: 1fr;
      gap: 20px;
      text-align: left;
    }

    .rm-process-pe__step-media,
    .rm-process-pe__step--reverse .rm-process-pe__step-media {
      grid-column: 1;
      grid-row: 1;
      aspect-ratio: 16 / 10;
    }

    .rm-process-pe__step-body,
    .rm-process-pe__step--reverse .rm-process-pe__step-body {
      grid-column: 1;
      grid-row: 2;
      text-align: left;
    }

    .rm-process-pe__step-title,
    .rm-process-pe__step--reverse .rm-process-pe__step-title {
      justify-content: flex-start;
    }

    .rm-process-pe__step-text,
    .rm-process-pe__step--reverse .rm-process-pe__step-text {
      margin-left: 0;
      max-width: none;
    }
  }

  @media (max-width: 480px) {
    .rm-process-pe {
      padding: 64px 16px 72px;
    }
  }
</style>

<script>
  (function () {
    var section = document.querySelector('.rm-process-pe');
    if (!section) return;

    /* Carga GSAP + ScrollTrigger por CDN una sola vez por página, aunque
       haya varios bloques de este tipo (reutiliza la instancia si otro
       bloque de esta misma página ya la cargó). */
    function loadScript(src) {
      return new Promise(function (resolve, reject) {
        var existing = document.querySelector('script[data-gsap-src="' + src + '"]');
        if (existing) {
          if (existing.dataset.loaded === 'true') { resolve(); return; }
          existing.addEventListener('load', resolve);
          existing.addEventListener('error', reject);
          return;
        }
        var s = document.createElement('script');
        s.src = src;
        s.dataset.gsapSrc = src;
        s.onload = function () { s.dataset.loaded = 'true'; resolve(); };
        s.onerror = reject;
        document.head.appendChild(s);
      });
    }

    function withGSAP(callback) {
      if (window.gsap && window.ScrollTrigger) { callback(); return; }
      Promise.all([
        loadScript('https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js'),
        loadScript('https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/ScrollTrigger.min.js')
      ]).then(function () {
        if (window.gsap && window.ScrollTrigger) callback();
      }).catch(function () {
        /* Sin GSAP el contenido ya es visible por CSS: no hace falta nada más. */
      });
    }

    withGSAP(function () {
      gsap.registerPlugin(ScrollTrigger);
      var mm = gsap.matchMedia();

      mm.add('(prefers-reduced-motion: no-preference)', function () {
        var head = section.querySelector('.rm-process-pe__head');
        if (head) {
          gsap.from(head, {
            y: 22,
            autoAlpha: 0,
            duration: 0.7,
            ease: 'power2.out',
            clearProps: 'transform,opacity,visibility',
            scrollTrigger: { trigger: head, start: 'top 85%', toggleActions: 'play none none reverse' }
          });
        }

        section.querySelectorAll('.rm-process-pe__step').forEach(function (step) {
          var media = step.querySelector('.rm-process-pe__step-media');
          var num = step.querySelector('.rm-process-pe__step-num');
          var title = step.querySelector('.rm-process-pe__step-title');
          var text = step.querySelector('.rm-process-pe__step-text');

          var tl = gsap.timeline({
            scrollTrigger: { trigger: step, start: 'top 80%', toggleActions: 'play none none reverse' }
          });

          tl.from(media, { scale: 0.9, autoAlpha: 0, duration: 0.6, ease: 'power2.out', clearProps: 'transform,opacity,visibility' })
            .from([num, title, text], { y: 16, autoAlpha: 0, duration: 0.5, ease: 'power2.out', stagger: 0.08, clearProps: 'transform,opacity,visibility' }, '-=0.35');
        });

        var spine = section.querySelector('.rm-process-pe__spine');
        var wrap = section.querySelector('.rm-process-pe__timeline-wrap');
        if (spine && wrap && window.matchMedia('(min-width: 861px)').matches) {
          gsap.fromTo(spine, { scaleY: 0 }, {
            scaleY: 1,
            ease: 'none',
            scrollTrigger: { trigger: wrap, start: 'top 75%', end: 'bottom 75%', scrub: 0.3 }
          });
        }

        section.querySelectorAll('.rm-process-pe__step-media svg').forEach(function (icon, i) {
          gsap.to(icon, {
            y: -5,
            duration: 2.2,
            ease: 'sine.inOut',
            repeat: -1,
            yoyo: true,
            delay: i * 0.25
          });
        });
      });
    });
  })();
</script>
